#[effects(alloc)]
#[uses(wide::small)]
fn int_lit(file: u32, text: &str, start: usize, out: &mut Vec<Token>, diags: &mut diag::Diags) -> usize
    requires start < text.len(),
{
    let n: usize = text.len();
    let c1: u32 = at(text, start, 1);
    let mut base: u64 = 10;
    if at(text, start, 0) == 48 {
        if c1 == 120 {
            base = 16;
        } else if c1 == 111 {
            base = 8;
        } else if c1 == 98 {
            base = 2;
        }
    }
    let mut i: usize = start;
    if base != 10 {
        i = fwd(start, 2, n);
    }
    let mut v: wide::U128 = wide::zero();
    let mut overflow: bool = false;
    let mut any: bool = false;
    let mut bad: bool = false;
    let mut bad_at: usize = 0;
    while i < n && (digit(at(text, i, 0)) || at(text, i, 0) == 95 || base == 16 && hexval(at(text, i, 0)) < 16)
        invariant i <= n, base == 10 || base == 16 || base == 8 || base == 2,
        decreases n - i,
    {
        let c: u32 = at(text, i, 0);
        if c != 95 {
            any = true;
            let d: u64 = hexval(c) as u64;
            if d >= base {
                if !bad {
                    bad = true;
                    bad_at = i;
                }
            } else {
                match wide::mul_add(v, base, d) {
                    None => { overflow = true; },
                    Some(x) => { v = x; },
                }
            }
        }
        i = i + 1;
    }
    let digits_end: usize = i;
    let mut name: String = String::from("decimal");
    let mut radix: ast::Radix = ast::Radix::Dec;
    if base == 16 {
        name = String::from("hexadecimal");
        radix = ast::Radix::Hex;
    } else if base == 8 {
        name = String::from("octal");
        radix = ast::Radix::Oct;
    } else if base == 2 {
        name = String::from("binary");
        radix = ast::Radix::Bin;
    }
    if bad {
        let mut m: String = joined("`", cut(text, bad_at, bad_at.saturating_add(1)).as_str(), "` is not ");
        if base == 8 {
            m.push_str("an ");
        } else {
            m.push_str("a ");
        }
        m.push_str(name.as_str());
        m.push_str(" digit");
        let mut h: String = String::from(name.as_str());
        if base == 2 {
            h.push_str(" digits are `0` and `1`");
        } else {
            h.push_str(" digits are `0` to `7`");
        }
        h.push_str("; write the value in another base (`0x` hexadecimal, or decimal)");
        diags.push(diag::fix(diag::new("E0108", span(file, bad_at, bad_at.saturating_add(1)), m.as_str()), h.as_str(), None));
    }
    let no_digits: bool = !any && base != 10;
    if no_digits {
        let mut m: String = joined("`", cut(text, start, digits_end).as_str(), "` has no ");
        m.push_str(name.as_str());
        m.push_str(" digits");
        let h: String = joined("write the digits after the prefix: `", ast::radix_text(radix, wide::zero()).as_str(), "`");
        diags.push(diag::fix(diag::new("E0108", span(file, start, digits_end), m.as_str()), h.as_str(), None));
    }
    if word(at(text, i, 0)) {
        let slo: usize = i;
        while i < n && word(at(text, i, 0))
            decreases n - i,
        {
            i = i + 1;
        }
        let suffix: String = cut(text, slo, i);
        if !no_digits {
            let g: diag::Diag = diag::new("E0104", span(file, start, i), joined("literal suffix `", suffix.as_str(), "` is not allowed").as_str());
            if int_type(suffix.as_str()) {
                diags.push(diag::fix(g, "remove the suffix", Some(cut(text, start, digits_end))));
            } else {
                diags.push(diag::fix(g, "integer literals are digits in base 10, or after `0x`, `0o` or `0b`", None));
            }
        }
    }
    if overflow {
        diags.push(diag::new("E0105", span(file, start, i), "integer literal does not fit in 128 bits"));
    }
    out.push(Token { tok: Tok::Int(v, radix), span: span(file, start, i) });
    i
}

impl Checker {
    #[effects(alloc)]
    fn check_rationale(self: &mut Checker, a: &ast::Attr) -> () {
        let mut kind: bool = false;
        let mut kind_written: bool = false;
        let mut text: bool = false;
        let mut bad: Vec<String> = Vec::new();
        for i in 0..a.args.len()
            invariant 0 <= i && i <= a.args.len(),
        {
            match &a.args[i] {
                ast::AttrArg::Ident(id) => bad.push(types::cat3("`", id.name.as_str(), "` needs a key (`kind = ..`)")),
                ast::AttrArg::Str(s, sp) => { if blank(s.as_str()) { bad.push(String::from("the explanation is empty")); } if text { bad.push(String::from("one explanation, as one string")); } text = true; },
                ast::AttrArg::Pair(k, v) => { if k.name.as_str() == "kind" { kind_written = true; if rationale_kind(&**v) { if kind { bad.push(String::from("`kind` is given twice")); } kind = true; } else { bad.push(String::from("`kind` is one of `nonlinear`, `solver_limit`, `boundary`, `performance`")); } } else if k.name.as_str() == "hash" { if !is_str_arg(&**v) { bad.push(String::from("`hash` is a string (the tools write it)")); } } else { bad.push(types::cat3("unknown key `", k.name.as_str(), "`")); } },
            }
        }
        if !kind_written {
            bad.push(String::from("`kind = ..` is missing"));
        }
        if !text {
            bad.push(String::from("the explanation (a string) is missing"));
        }
        if bad.len() > 0 {
            self.help("E1002", a.span, types::cat2("malformed rationale: ", types::join(bad.as_slice(), "; ").as_str()).as_str(), "write `#[rationale(kind = K, \"why the fact holds\")]`, `K` one of `nonlinear`, `solver_limit`, `boundary`, `performance`");
        }
    }

    #[effects(alloc)]
    fn fn_effect(self: &mut Checker, f: &ast::FnDef) -> types::Effects {
        let mut effect: types::Effects = types::pure();
        let mut have: bool = false;
        for i in 0..f.attrs.len()
            invariant 0 <= i && i <= f.attrs.len(),
        {
            let an: String = f.attrs[i].name.name.clone();
            let span: source::Span = f.attrs[i].span;
            if an.as_str() == "effects" {
                if is_proof(&f.kind) {
                    self.fixed("E0256", span, "a `proof fn` has no effect: it is ghost code, erased before it runs", "remove the attribute", "");
                } else if is_spec(&f.kind) {
                    self.fixed("E0604", span, "spec functions are pure by definition", "remove the attribute", "");
                } else if have {
                    self.fixed("E0605", span, "duplicate `#[effects(..)]` attribute", "remove the attribute", "");
                } else {
                    effect = self.effects_attr(&f.attrs[i]);
                    have = true;
                }
            } else if an.as_str() == "uses" {} else if an.as_str() == "external_body" {
                if !is_exec(&f.kind) || f.name.name.as_str() == "main" {
                    self.fixed("E1004", span, "`#[external_body]` is for an executable function other than `main`", "remove the attribute", "");
                } else if !has_attr(f.attrs.as_slice(), "rationale") {
                    self.missing_rationale(span, "`#[external_body]`");
                }
            } else if an.as_str() == "rationale" {
                if !has_attr(f.attrs.as_slice(), "external_body") {
                    self.fixed("E1002", span, "a rationale on a function that is not `#[external_body]`", "remove it: a rationale stands before `#[external_body]` or an `assume`", "");
                } else {
                    self.check_rationale(&f.attrs[i]);
                }
            } else if an.as_str() == "summary" {
                self.check_summary(&f.attrs[i], f.attrs.as_slice());
            } else {
                self.fixed("E0605", span, types::cat3("unknown attribute `", an.as_str(), "` on a function").as_str(), "remove it: functions take `#[summary(\"..\")]`, `#[effects(..)]`, `#[uses(..)]`, `#[external_body]` and `#[rationale(..)]`", "");
            }
        }
        if is_exec(&f.kind) && !have {
            let hi: u32 = if f.span.lo < 4294967293 {
                f.span.lo + 2
            } else {
                f.span.lo
            };
            self.fixed("E0601", source::Span { file: f.span.file, lo: f.span.lo, hi: hi }, types::cat3("`", f.name.name.as_str(), "` has no `#[effects(..)]` attribute").as_str(), "add `#[effects(pure)]` above the function", "#[effects(pure)]\nfn");
        }
        effect
    }
}

impl Parser {
    #[effects(alloc)]
    fn parse_stmt(self: &mut Parser, d: usize) -> Option<StmtOrTail>
        requires d <= 256,
        decreases (256 - d) * 64 + 31,
    {
        let lo: source::Span = self.span();
        if self.is_p("#") && self.t.is_p(1, "[") && !self.t.is_kw(2, "trigger") {
            let attrs: Vec<ast::Attr> = self.attrs();
            let before_assume: bool = self.is_kw("assume") && self.t.is_p(1, "(");
            let mut rationale: Option<ast::Attr> = None;
            let mut taken: bool = false;
            let mut rest: Vec<ast::Attr> = attrs;
            let mut k: usize = rest.len();
            let mut kept: Vec<ast::Attr> = Vec::new();
            while k > 0
                decreases k,
            {
                k = k - 1;
                match rest.pop() {
                    None => {},
                    Some(a) => kept.push(a),
                }
            }
            let mut j: usize = kept.len();
            while j > 0
                decreases j,
            {
                j = j - 1;
                match kept.pop() {
                    None => {},
                    Some(a2) => { if a2.name.name == "rationale" && before_assume && !taken { taken = true; rationale = Some(a2); } else { let mut msg: String = String::from("`#["); msg.push_str(a2.name.name.as_str()); msg.push_str("]` is not allowed here: before a statement, only `#[rationale(..)]` before `assume(..)`"); self.err_rep("E1002", a2.span, msg.as_str(), "remove the attribute", ""); } },
                }
            }
            if before_assume {
                return self.parse_assume(lo, rationale, d);
            }
        }
        if self.is_kw("assume") && self.t.is_p(1, "(") {
            return self.parse_assume(lo, None, d);
        }
        if self.is_kw("admit") && self.t.is_p(1, "(") {
            self.bump();
            self.bump();
            let close: source::Span = self.expect_p(")")?;
            let ahi: source::Span = if self.is_p(";") {
                self.expect_p(";")?
            } else {
                close
            };
            self.err_fix("E0217", lo.to(ahi), "Verus's `admit()` is not used", "state what you take as given: `assume(p(..));` with a `#[rationale(kind = .., \"why\")]` before it, or prove it");
            return Some(StmtOrTail::Stmt(ast::Stmt::Expr(ast::Expr { kind: ast::ExprKind::Block(ast::Block { stmts: Vec::new(), tail: None, span: lo.to(ahi) }), span: lo.to(ahi) })));
        }
        if self.is_kw("let") {
            return Some(StmtOrTail::Stmt(self.parse_let(d)?));
        }
        if self.is_kw("while") {
            if !self.enter(d) {
                return None;
            }
            return Some(StmtOrTail::Stmt(self.parse_while_inner(None, d + 1)?));
        }
        if self.is_kw("assert") && self.t.is_p(1, "(") {
            self.bump();
            self.bump();
            let cond: ast::Expr = self.parse_expr(d)?;
            let cclose: source::Span = self.expect_p(")")?;
            let block: bool = self.is_kw("by") && self.t.is_p(1, "{");
            let by: Option<ast::Prover> = self.parse_by(cclose);
            let shi: source::Span = if block && !self.is_p(";") {
                self.prev_span()
            } else {
                self.expect_p(";")?
            };
            return Some(StmtOrTail::Stmt(ast::Stmt::Assert(ast::Assert { cond: cond, by: by, span: lo.to(shi) })));
        }
        if self.is_kw("for") {
            if !self.enter(d) {
                return None;
            }
            return Some(StmtOrTail::Stmt(self.parse_for(None, d + 1)?));
        }
        if self.is_kw("proof") && self.t.is_p(1, "{") {
            self.bump();
            if !self.enter(d) {
                return None;
            }
            let body: ast::Block = self.parse_block(d + 1)?;
            let pspan: source::Span = lo.to(body.span);
            self.eat_p(";");
            return Some(StmtOrTail::Stmt(ast::Stmt::Proof(ast::ProofBlock { body: body, span: pspan })));
        }
        if self.t.kind(0) == 8 && self.t.is_p(1, ":") && (self.t.is_kw(2, "while") || self.t.is_kw(2, "for")) {
            let lname: String = text_of(self.t.label());
            let lspan: source::Span = self.bump();
            self.bump();
            let label: ast::Ident = ast::Ident { name: lname, span: lspan };
            if !self.enter(d) {
                return None;
            }
            if self.is_kw("for") {
                return Some(StmtOrTail::Stmt(self.parse_for(Some(label), d + 1)?));
            }
            return Some(StmtOrTail::Stmt(self.parse_while_inner(Some(label), d + 1)?));
        }
        let labeled_loop: bool = self.t.kind(0) == 8 && self.t.is_p(1, ":") && self.t.is_kw(2, "loop");
        if self.is_kw("if") || self.is_kw("match") || self.is_kw("loop") || labeled_loop {
            let pos: usize = self.t.pos;
            let nd: usize = self.diags.items.len();
            if !self.enter(d) {
                return None;
            }
            let e: ast::Expr = if self.is_kw("if") {
                self.parse_if(d + 1)?
            } else if self.is_kw("match") {
                self.parse_match(d + 1)?
            } else {
                self.parse_loop(d + 1)?
            };
            let k0: u8 = self.t.kind(0);
            let ends: bool = if k0 == 7 {
                self.is_p("*") || self.is_p("-") || self.is_p("&") || self.is_p("!") || self.is_p("(") || self.is_p("[") || self.is_p(";") || self.is_p("}") || self.is_p("{")
            } else if k0 == 0 {
                !self.is_kw("as")
            } else {
                true
            };
            if ends {
                if self.eat_p(";") {
                    return Some(StmtOrTail::Stmt(ast::Stmt::Expr(e)));
                }
                return Some(StmtOrTail::Tail(e));
            }
            self.t.back(pos);
            self.diags.items.truncate(nd);
        }
        match self.compound_assign(lo, d)? {
            Compound::No => {},
            Compound::Yes(cs) => { return Some(StmtOrTail::Stmt(cs)); },
        }
        let target: ast::Expr = self.parse_expr(d)?;
        if self.eat_p("=") {
            let value: ast::Expr = self.parse_expr(d)?;
            let vhi: source::Span = self.expect_p(";")?;
            return Some(StmtOrTail::Stmt(ast::Stmt::Assign(ast::Assign { target: target, value: value, span: lo.to(vhi) })));
        }
        if self.eat_p(";") {
            return Some(StmtOrTail::Stmt(ast::Stmt::Expr(target)));
        }
        if self.is_p("}") || block_like(&target) {
            return Some(StmtOrTail::Tail(target));
        }
        self.err_expected("`;`");
        None
    }
}

impl Checker {
    #[effects(alloc)]
    fn box_type(self: &mut Checker, span: source::Span, args: &[ast::Type], mp: &str, report: bool, f: usize) -> ast::TypeKind
        decreases f * 2,
    {
        if f == 0 {
            return ast::TypeKind::Error;
        }
        if args.len() != 1 {
            if report {
                self.err("E0420", span, count1("`Box` takes 1 type argument, found ", args.len()).as_str());
            }
            return ast::TypeKind::Error;
        }
        let e: ast::TypeKind = self.canon(&args[0], mp, report, f - 1);
        if types::is_error(&e) {
            return ast::TypeKind::Error;
        }
        if not_value(&e) {
            if report {
                self.help("E0402", args[0].span, types::cat3("a `Box` holds a value, found `", types::text(&e).as_str(), "`").as_str(), "box a scalar, a struct or enum, an array or another `Box`");
            }
            return ast::TypeKind::Error;
        }
        ast::TypeKind::Box(Box::new(ast::Type { kind: e, span: args[0].span }))
    }

    #[effects(alloc)]
    fn canon_named(self: &mut Checker, span: source::Span, path: &[String], args: &[ast::Type], mp: &str, report: bool, f: usize) -> ast::TypeKind
        decreases f * 2,
    {
        if f == 0 || path.len() == 0 {
            return ast::TypeKind::Error;
        }
        if path.len() == 1 && types::is_tparam(self.tparams.as_slice(), path[0].as_str()) {
            if args.len() > 0 && report {
                self.fixed("E0420", span, types::cat3("type parameter `", path[0].as_str(), "` takes no type arguments").as_str(), types::cat3("write `", path[0].as_str(), "`").as_str(), path[0].as_str());
            }
            return ast::TypeKind::Param(path[0].clone());
        }
        let name: String = types::join(path, "::");
        if name.as_str() == "Self" {
            let head: Option<ast::TypeKind> = match &self.self_head {
                None => None,
                Some(sh) => Some(sh.head.clone()),
            };
            match head {
                None => {},
                Some(h) => { if report { let d: diag::Diag = self.unknown_type(path, span, mp); self.diags.push(d); } return h; },
            }
        }
        if path.len() == 1 && name.as_str() == "Vec" {
            return self.vec_type(span, args, mp, report, f - 1);
        }
        if path.len() == 1 && name.as_str() == "Box" {
            return self.box_type(span, args, mp, report, f - 1);
        }
        let last_s: String = path[path.len() - 1].clone();
        let here: String = types::cat3(mp, "::", name.as_str());
        if (path.len() == 1 || path[0].as_str() == "std") && (last_s.as_str() == "Rc" || last_s.as_str() == "RefCell" || last_s.as_str() == "Cell" || last_s.as_str() == "Arc") && !self.adts.has(here.as_str()) {
            if report {
                self.help("E0238", span, types::cat3("`", last_s.as_str(), "` is not used: values have one owner").as_str(), "hold the value in an owned tree (`Box`, `Vec`) or refer to it by an index into a `Vec` (ADR-0047 §5)");
            }
            return ast::TypeKind::Error;
        }
        if path.len() == 1 && name.as_str() == "String" && !self.adts.has(here.as_str()) {
            if args.len() > 0 {
                if report {
                    self.err("E0420", span, "`String` takes no type arguments");
                }
                return ast::TypeKind::Error;
            }
            return ast::TypeKind::String;
        }
        if path.len() == 1 && (name.as_str() == "Option" || name.as_str() == "Result") {
            let want: usize = if name.as_str() == "Option" {
                1
            } else {
                2
            };
            if args.len() != want {
                if report {
                    self.err("E0420", span, counts(types::cat3("`", name.as_str(), "` takes ").as_str(), want, " type argument(s), found ", args.len(), "").as_str());
                }
                return ast::TypeKind::Error;
            }
            let out: Vec<ast::Type> = self.canon_args(args, mp, report, f - 1);
            for i in 0..out.len()
                invariant 0 <= i && i <= out.len(),
            {
                if is_ref_like(&out[i].kind) {
                    if report {
                        self.help("E0403", out[i].span, types::cat5("type argument `", types::text(&out[i].kind).as_str(), "` of `", name.as_str(), "` is not a value type").as_str(), "type arguments are value types: references are second-class (ADR-0015)");
                    }
                    return ast::TypeKind::Error;
                }
            }
            let mut p: Vec<String> = Vec::new();
            p.push(path[0].clone());
            return ast::TypeKind::Named(p, out);
        }
        let full: String = if path.len() == 1 {
            here
        } else {
            let dropped: String = here;
            name.clone()
        };
        match self.adts.find(full.as_str()) {
            None => { if report { let d: diag::Diag = self.unknown_type(path, span, mp); self.diags.push(d); } ast::TypeKind::Error },
            Some(at) => { let ps: Vec<types::TParam> = self.adts.items[at].generics.clone(); if args.len() != ps.len() { if report { let wanted: String = if ps.len() == 0 { types::cat5("`", name.as_str(), "` has no type parameters: write `", name.as_str(), "`") } else { types::cat5("write one type for each parameter: `", name.as_str(), "<", param_names(ps.as_slice(), ", ").as_str(), ">`") }; self.help("E0420", span, counts(types::cat3("`", name.as_str(), "` takes ").as_str(), ps.len(), " type argument(s), found ", args.len(), "").as_str(), wanted.as_str()); } return ast::TypeKind::Error; } let out: Vec<ast::Type> = self.canon_args(args, mp, report, f - 1); let mut ok: bool = true; for i in 0..out.len() invariant 0 <= i && i <= out.len(), { if i < ps.len() { if !self.targ_ok(&out[i].kind, &ps[i], name.as_str(), out[i].span, report) { ok = false; } } } if !ok { return ast::TypeKind::Error; } ast::TypeKind::Named(refs::split_path(full.as_str()), out) },
        }
    }

    #[effects(alloc)]
    fn collect_impl(self: &mut Checker, m: &ast::Mod, i: usize, mp: &str, with_impl: &mut Vec<String>, impl_tys: &mut Vec<String>, impl_names: &mut Vec<Vec<String>>) -> ()
        requires i < m.impls.len() && impl_tys.len() == impl_names.len(),
        ensures impl_tys.len() == impl_names.len(),
    {
        let tyname: String = m.impls[i].ty.name.clone();
        let ty: String = types::cat3(mp, "::", tyname.as_str());
        let mut declared: bool = false;
        for t in 0..m.types.len()
            invariant 0 <= t && t <= m.types.len(),
        {
            if m.types[t].name.name.as_str() == tyname.as_str() {
                declared = true;
            }
        }
        if !declared {
            self.err("E0308", m.impls[i].ty.span, types::cat5("`impl ", tyname.as_str(), "` needs the type declared in the same unit `", mp, "`").as_str());
            return;
        }
        let ig: Vec<types::TParam> = self.tparams_of(m.impls[i].generics.as_slice(), true, mp);
        let key: String = types::cat3(ty.as_str(), "\n", bounds_key(ig.as_slice()).as_str());
        if !types::add(with_impl, key.as_str()) {
            self.help("E0308", m.impls[i].ty.span, types::cat3("`", tyname.as_str(), "` already has an `impl` block with these bounds; one per list of bounds").as_str(), "move these functions into the first block with the same bounds (ADR-0097)");
            return;
        }
        let ps: Vec<String> = match self.adts.find(ty.as_str()) {
            None => Vec::new(),
            Some(at) => tparam_names(self.adts.items[at].generics.as_slice()),
        };
        let mut in_order: bool = ig.len() == ps.len() && m.impls[i].ty_args.len() == ig.len();
        for a in 0..m.impls[i].ty_args.len()
            invariant 0 <= a && a <= m.impls[i].ty_args.len() && i < m.impls.len(),
        {
            if a < ig.len() {
                match plain_name(&m.impls[i].ty_args[a].kind) {
                    None => { in_order = false; },
                    Some(w) => { if w.as_str() != ig[a].name.as_str() { in_order = false; } },
                }
            }
        }
        if !in_order {
            let r: String = if ps.len() == 0 {
                types::cat2("impl ", tyname.as_str())
            } else {
                types::cat7("impl<", copy_list(ps.as_slice()).as_str(), "> ", tyname.as_str(), "<", types::join(ps.as_slice(), ", ").as_str(), ">")
            };
            self.help("E0420", m.impls[i].ty.span, types::cat3("the `impl` of `", tyname.as_str(), "` takes its type parameters in order").as_str(), types::cat3("write `", r.as_str(), "`").as_str());
            return;
        }
        let mut slot: usize = impl_tys.len();
        for s in 0..impl_tys.len()
            invariant 0 <= s && s <= impl_tys.len() && slot <= impl_tys.len(),
        {
            if impl_tys[s].as_str() == ty.as_str() {
                slot = s;
            }
        }
        if slot == impl_tys.len() {
            impl_tys.push(ty.clone());
            impl_names.push(Vec::new());
        }
        let mut dup: Vec<source::Span> = Vec::new();
        for k in 0..m.impls[i].fns.len()
            invariant 0 <= k && k <= m.impls[i].fns.len() && i < m.impls.len() && slot < impl_names.len() && impl_tys.len() == impl_names.len(),
        {
            if !types::add(&mut impl_names[slot], m.impls[i].fns[k].name.name.as_str()) {
                dup.push(m.impls[i].fns[k].name.span);
            }
        }
        for k in 0..m.impls[i].fns.len()
            invariant 0 <= k && k <= m.impls[i].fns.len() && i < m.impls.len(),
        {
            let fname: String = m.impls[i].fns[k].name.name.clone();
            if has_span(dup.as_slice(), m.impls[i].fns[k].name.span) {
                self.help("E0302", m.impls[i].fns[k].name.span, types::cat5("`", fname.as_str(), "` is defined more than once in the `impl` blocks of `", tyname.as_str(), "`").as_str(), "a name is one function of the type, whichever block holds it: rename one or remove it");
            } else {
                let fg: Vec<types::TParam> = self.tparams_of(m.impls[i].fns[k].generics.as_slice(), false, mp);
                let mut tps: Vec<types::TParam> = ig.clone();
                ast::append::<types::TParam>(&mut tps, fg);
                self.tparams = tps;
                self.receiver_rule(&m.impls[i].fns[k], ty.as_str(), true, mp);
                self.tparams = Vec::new();
                self.collect_fn(&m.impls[i].fns[k], types::cat3(ty.as_str(), "::", fname.as_str()).as_str(), mp, true, ig.as_slice());
            }
        }
    }

    #[effects(alloc)]
    fn impl_head(self: &mut Checker, i: &ast::TraitImpl, mp: &str) -> () {
        if i.trait_path.len() == 0 {
            return;
        }
        let name: String = path_text(i.trait_path.as_slice());
        let tspan: source::Span = span_to(i.trait_path[0].span, i.trait_path[i.trait_path.len() - 1].span);
        let found: Option<String> = self.trait_path(i.trait_path.as_slice(), mp);
        let tr: String = match found {
            None => { let help: String = match self.type_path(i.trait_path.as_slice(), mp) { None => String::from("a trait of another unit is named by full path, e.g. `unit::Shape`"), Some(tp) => types::cat5("`", name.as_str(), "` is a type; its own functions go in `impl ", name.as_str(), " { .. }`"), }; let d: diag::Diag = self.unknown_trait(name.as_str(), tspan, mp, help.as_str()); self.diags.push(d); return; },
            Some(x) => x,
        };
        let gens: Vec<types::TParam> = self.tparams_of(i.generics.as_slice(), true, mp);
        self.tparams = gens.clone();
        let head: ast::TypeKind = self.canon(&i.self_ty, mp, true, 100000);
        self.tparams = Vec::new();
        let span: source::Span = i.self_ty.span;
        if types::is_error(&head) {
            return;
        }
        let info: types::TraitImplInfo = types::TraitImplInfo { trait_path: tr.clone(), generics: gens.clone(), head: head.clone(), unit: String::from(mp), span: i.span };
        match types::param_name(&head) {
            None => {},
            Some(n) => { self.help("E0235", span, types::cat4(types::cat5("`impl<", n.as_str(), "> ", name.as_str(), " for ").as_str(), n.as_str(), types::cat3("` implements `", name.as_str(), "` for every type (a blanket impl)").as_str(), "").as_str(), types::cat5("implement it for each type: `impl ", name.as_str(), " for Point { .. }`, or bound a type parameter `T: ", name.as_str(), "` where it is used").as_str()); self.rejected_impls.push(info); return; },
        }
        let mut cb: Vec<String> = Vec::new();
        cb.push(String::from("Copy"));
        let copy: types::TParam = types::TParam { name: String::from("Self"), bounds: cb };
        if !self.targ_ok(&head, &copy, tr.as_str(), span, true) {
            return;
        }
        let ht: String = types::text_in(&head, mp);
        for g in 0..gens.len()
            invariant 0 <= g && g <= gens.len(),
        {
            if !types::mentions_param(&head, gens[g].name.as_str(), 100000) {
                let at: source::Span = if g < i.generics.len() {
                    i.generics[g].span
                } else {
                    span
                };
                self.help("E0420", at, types::cat5("type parameter `", gens[g].name.as_str(), "` of the impl does not appear in `", ht.as_str(), "`").as_str(), "remove it, or use it in the implemented type");
                self.rejected_impls.push(info);
                return;
            }
        }
        let mut seen: Vec<String> = Vec::new();
        types::params_in(&head, &mut seen, 100000);
        if !same_names(seen.as_slice(), gens.as_slice()) {
            self.help("E0420", span, types::cat3("the `impl` for `", ht.as_str(), "` takes its type parameters in order").as_str(), types::cat3("declare them in the order the type names them: `", types::join(seen.as_slice(), "`, `").as_str(), "`").as_str());
            self.rejected_impls.push(info);
            return;
        }
        let trait_unit: String = unit_of(tr.as_str());
        let type_unit: Option<String> = match types::named_path(&head) {
            None => None,
            Some(hp) => { if self.adts.has(hp.as_str()) { Some(unit_of(hp.as_str())) } else { None } },
        };
        let in_type_unit: bool = match &type_unit {
            None => false,
            Some(u) => u.as_str() == mp,
        };
        if mp != trait_unit.as_str() && !in_type_unit {
            let help: String = match &type_unit {
                None => types::cat3("move it to unit `", trait_unit.as_str(), "`"),
                Some(u) => { if u.as_str() != trait_unit.as_str() { types::cat5("move it to unit `", trait_unit.as_str(), "` or unit `", u.as_str(), "`") } else { types::cat3("move it to unit `", trait_unit.as_str(), "`") } },
            };
            self.help("E0312", span, types::cat5("`impl ", name.as_str(), " for ", ht.as_str(), "` is in neither the unit of the trait nor the unit of the type").as_str(), help.as_str());
            self.rejected_impls.push(info);
            return;
        }
        let mut prev: Option<String> = None;
        for p in 0..self.trait_impls.len()
            invariant 0 <= p && p <= self.trait_impls.len(),
        {
            if !has_text(&prev) && self.trait_impls[p].trait_path.as_str() == tr.as_str() && types::overlaps(&self.trait_impls[p].head, &head, 100000) {
                prev = Some(types::text_in(&self.trait_impls[p].head, mp));
            }
        }
        match prev {
            None => {},
            Some(pt) => { self.help("E0311", span, types::cat4(types::cat5("`impl ", name.as_str(), " for ", ht.as_str(), "` overlaps `impl ").as_str(), name.as_str(), " for ", types::cat2(pt.as_str(), "`").as_str()).as_str(), "a trait has one impl for a type: remove one of them, or make their types differ"); self.overlapping_impls.push(info.span); self.rejected_impls.push(info); return; },
        }
        self.trait_impls.push(info);
    }

    #[effects(alloc)]
    fn resolve_kind(self: &mut Checker, t: &ast::TypeDef, path: &str, mp: &str) -> types::AdtKind {
        match &t.kind {
            ast::TypeDefKind::Struct(fields) => { if fields.len() == 0 { self.err("E0420", t.name.span, "a struct needs at least one field"); } let mut seen: Vec<String> = Vec::new(); let mut out: Vec<types::FieldSig> = Vec::new(); for i in 0..fields.len() invariant 0 <= i && i <= fields.len(), { if !types::add(&mut seen, fields[i].name.name.as_str()) { self.err("E0302", fields[i].name.span, types::cat5("field `", fields[i].name.name.as_str(), "` is defined more than once in `", path, "`").as_str()); } let ty: ast::TypeKind = self.field_type(&fields[i].ty, mp); out.push(types::FieldSig { name: fields[i].name.name.clone(), ty: ty }); } types::AdtKind::Struct(out) },
            ast::TypeDefKind::Enum(variants) => { if variants.len() == 0 { self.err("E0420", t.name.span, "an enum needs at least one variant"); } let mut seen: Vec<String> = Vec::new(); let mut vout: Vec<types::VariantSig> = Vec::new(); for i in 0..variants.len() invariant 0 <= i && i <= variants.len(), { if !types::add(&mut seen, variants[i].name.name.as_str()) { self.err("E0302", variants[i].name.span, types::cat5("variant `", variants[i].name.name.as_str(), "` is defined more than once in `", path, "`").as_str()); } let mut tys: Vec<ast::TypeKind> = Vec::new(); for j in 0..variants[i].payload.len() invariant 0 <= j && j <= variants[i].payload.len() && i < variants.len(), { let ty: ast::TypeKind = self.field_type(&variants[i].payload[j], mp); tys.push(ty); } vout.push(types::VariantSig { name: variants[i].name.name.clone(), tys: tys }); } types::AdtKind::Enum(vout) },
        }
    }

    #[effects(alloc)]
    fn vec_type(self: &mut Checker, span: source::Span, args: &[ast::Type], mp: &str, report: bool, f: usize) -> ast::TypeKind
        decreases f * 2,
    {
        if f == 0 {
            return ast::TypeKind::Error;
        }
        if args.len() != 1 {
            if report {
                self.err("E0420", span, count1("`Vec` takes 1 type argument, found ", args.len()).as_str());
            }
            return ast::TypeKind::Error;
        }
        let e: ast::TypeKind = self.canon(&args[0], mp, report, f - 1);
        if types::is_error(&e) {
            return ast::TypeKind::Error;
        }
        if !self.vec_elem_ok(&e, 100000) {
            if report {
                self.err("E0402", args[0].span, types::cat3("`Vec` elements are scalars, structs and enums without arrays, or `Vec`s and `Box`es of them, found `", types::text(&e).as_str(), "`").as_str());
            }
            return ast::TypeKind::Error;
        }
        ast::TypeKind::Vec(Box::new(ast::Type { kind: e, span: args[0].span }))
    }
}

impl Body {
    #[effects(alloc)]
    fn struct_lit(self: &mut Body, cx: &mut FnCtx, sl: &ast::StructLit, expected: &Option<ast::TypeKind>, span: source::Span, mode: Mode, f: usize) -> ast::TypeKind
        decreases f * 3,
    {
        let n: usize = sl.path.len();
        if f == 0 || n == 0 {
            return ast::TypeKind::Error;
        }
        let no: Option<ast::TypeKind> = None;
        let name: String = decls::path_text(sl.path.as_slice());
        let mut tp: String = String::new();
        let mut state: u8 = 0;
        let mut fs: Vec<types::FieldSig> = Vec::new();
        match self.c.type_path(sl.path.as_slice(), cx.mod_path.as_str()) {
            None => {},
            Some(p) => { state = 2; match self.c.adts.find(p.as_str()) { None => {}, Some(at) => { match &self.c.adts.items[at].kind { types::AdtKind::Struct(xs) => { state = 1; fs = xs.clone(); }, types::AdtKind::Enum(q4_vs) => {}, } }, } tp = p; },
        }
        if state == 2 {
            self.c.help("E0422", span, types::cat3("`", name.as_str(), "` is an enum, not a struct").as_str(), types::cat3("build a variant: `", name.as_str(), "::V(..)`").as_str());
        }
        if state == 0 {
            let tn: Vec<String> = names_of(sl.path.as_slice());
            let d: diag::Diag = self.c.unknown_type(tn.as_slice(), decls::span_to(sl.path[0].span, sl.path[n - 1].span), cx.mod_path.as_str());
            self.c.diags.push(d);
        }
        if state != 1 {
            for i in 0..sl.fields.len()
                invariant 0 <= i && i <= sl.fields.len(),
            {
                self.expr(cx, &sl.fields[i].value, &no, mode, f - 1);
            }
            return ast::TypeKind::Error;
        }
        let fnames: Vec<String> = field_names(fs.as_slice());
        let ps: Vec<types::TParam> = match self.c.adts.find(tp.as_str()) {
            None => Vec::new(),
            Some(at2) => self.c.adts.items[at2].generics.clone(),
        };
        let mut tm: types::Subst = self.expected_args(tp.as_str(), expected);
        let mut slots: Vec<Slot> = Vec::new();
        let mut given: Vec<String> = Vec::new();
        let mut order: Vec<usize> = Vec::new();
        for j in 0..sl.fields.len()
            invariant 0 <= j && j <= sl.fields.len(),
        {
            if types::has(given.as_slice(), sl.fields[j].name.name.as_str()) {
                self.c.help("E0422", sl.fields[j].name.span, types::cat3("field `", sl.fields[j].name.name.as_str(), "` is given more than once").as_str(), "give each field once");
            } else {
                given.push(sl.fields[j].name.name.clone());
            }
            match decls::index_of(fnames.as_slice(), sl.fields[j].name.name.as_str()) {
                None => { let msg: String = types::cat5("`", tp.as_str(), "` has no field `", sl.fields[j].name.name.as_str(), "`"); match types::closest(sl.fields[j].name.name.as_str(), fnames.as_slice()) { None => self.c.help("E0306", sl.fields[j].name.span, msg.as_str(), types::cat4("fields of `", tp.as_str(), "`: ", types::join(fnames.as_slice(), ", ").as_str()).as_str()), Some(near) => self.c.fixed("E0306", sl.fields[j].name.span, msg.as_str(), types::cat3("did you mean `", near.as_str(), "`?").as_str(), near.as_str()), } self.expr(cx, &sl.fields[j].value, &no, mode, f - 1); },
                Some(k) => { if k < fs.len() { slots.push(Slot { at: j, ty: fs[k].ty.clone() }); order.push(k); } },
            }
        }
        let noargs: Vec<ast::Expr> = Vec::new();
        self.check_slots(cx, ps.as_slice(), &mut tm, noargs.as_slice(), sl.fields.as_slice(), true, slots.as_slice(), mode, f - 1);
        let whole: ast::TypeKind = if ps.len() == 0 {
            let targs: Vec<ast::Type> = Vec::new();
            ast::TypeKind::Named(refs::split_path(tp.as_str()), targs)
        } else {
            self.instance(tp.as_str(), &tm, types::cat3("`", sl.path[n - 1].name.as_str(), " { .. }`").as_str(), span)
        };
        let has_rest: bool = match &sl.rest {
            None => false,
            Some(q4_r) => true,
        };
        if !has_rest && order.len() == sl.fields.len() && given.len() == sl.fields.len() && unsorted(order.as_slice()) {
            let mut sorted: Vec<String> = Vec::new();
            for a in 0..fnames.len()
                invariant 0 <= a && a <= fnames.len(),
            {
                match field_at(sl.fields.as_slice(), fnames[a].as_str()) {
                    None => {},
                    Some(b) => sorted.push(types::cat3(fnames[a].as_str(), ": ", fmt::expr_text(&sl.fields[b].value).as_str())),
                }
            }
            self.c.fixed("E0434", span, types::cat5("the fields of `", tp.as_str(), "` are given out of their declaration order (", types::join(fnames.as_slice(), ", ").as_str(), ")").as_str(), "give the fields in declaration order (they are evaluated in the order written)", types::cat4(name.as_str(), " { ", types::join(sorted.as_slice(), ", ").as_str(), " }").as_str());
        }
        match &sl.rest {
            None => { let mut missing: Vec<String> = Vec::new(); for c in 0..fnames.len() invariant 0 <= c && c <= fnames.len(), { if !types::has(given.as_slice(), fnames[c].as_str()) { missing.push(fnames[c].clone()); } } if missing.len() > 0 { self.c.help("E0422", span, types::cat5("missing field(s) `", types::join(missing.as_slice(), "`, `").as_str(), "` of `", tp.as_str(), "`").as_str(), "give every field a value (ADR-0026: no `..` update syntax)"); } },
            Some(r) => { let hint: Option<ast::TypeKind> = Some(whole.clone()); let rt: ast::TypeKind = self.expr(cx, &**r, &hint, mode, f - 1); self.expect_ty(&rt, &whole, r.span); if var_or_field(&r.kind) { let base: String = fmt::expr_text(&**r); let mut all: Vec<String> = Vec::new(); for g in 0..fnames.len() invariant 0 <= g && g <= fnames.len(), { match field_at(sl.fields.as_slice(), fnames[g].as_str()) { None => all.push(types::cat5(fnames[g].as_str(), ": ", base.as_str(), ".", fnames[g].as_str())), Some(h) => all.push(types::cat3(fnames[g].as_str(), ": ", fmt::expr_text(&sl.fields[h].value).as_str())), } } self.c.fixed("E0223", span, "struct update syntax `..` is not allowed", "write every field", types::cat4(name.as_str(), " { ", types::join(all.as_slice(), ", ").as_str(), " }").as_str()); } else { self.c.help("E0223", span, "struct update syntax `..` is not allowed", "write every field: `f: base.f`"); } },
        }
        whole
    }
}

impl Body {
    #[effects(alloc)]
    fn call_kind(self: &mut Body, cx: &mut FnCtx, path: &[ast::Ident], targs: &[ast::TArgs], args: &[ast::Expr], sig: &types::FnSig, target: &str, quoted: &str, span: source::Span, mode: Mode) -> () {
        let caller: String = cx.path.clone();
        if is_proof(sig.kind) {
            if exec_mode(mode) {
                let whole: ast::Expr = ast::Expr { kind: ast::ExprKind::Call(ast::Call { path: idents(path), targs: targs_copy(targs), args: exprs_copy(args), method: None }), span: span };
                let r: String = types::cat3("proof { ", fmt::expr_text(&whole).as_str(), "; }");
                self.c.fixed("E0258", span, types::cat2(quoted, " is a `proof fn`: executable code calls it in a `proof { .. }` block").as_str(), types::cat3("wrap the call: `", r.as_str(), "`").as_str(), r.as_str());
            } else if ghost_mode(mode) {
                self.add_call(caller.as_str(), target);
            } else {
                self.c.help("E0258", span, types::cat2(quoted, " is a `proof fn` and has no value in a specification").as_str(), "call it as a statement of a `proof { .. }` block or a `proof fn`; its `ensures` then hold after the call");
            }
        } else if is_exec(sig.kind) {
            if exec_mode(mode) {
                need(cx, sig.effect, types::cat2("a call of ", quoted).as_str());
                if types::is_pure(cx.effect) && sig.effect.io {
                    self.c.help("E0603", span, types::cat5(quoted, " has effect `io`, but `", caller.as_str(), "` is `pure`", "").as_str(), types::cat3("declare `#[effects(io)]` on `", caller.as_str(), "`, or move the call out of it").as_str());
                }
                self.add_call(caller.as_str(), target);
            } else if ghost_mode(mode) || cx.ghost {
                self.ghost_violation(span, types::cat2("a call of executable function ", quoted).as_str(), "call it outside the `proof` block, or state the fact with a spec fn or a `proof fn`");
            } else {
                self.c.err("E0504", span, types::cat2(quoted, " is executable and cannot be called from a specification").as_str());
            }
        } else if exec_mode(mode) {
            self.c.err("E0505", span, types::cat2(quoted, " is a spec function and cannot be called from executable code").as_str());
        } else {
            self.add_call(caller.as_str(), target);
        }
    }
}

#[effects(alloc)]
#[uses(wide::small)]
fn int_lit(file: u32, text: &str, start: usize, out: &mut Vec<Token>, diags: &mut diag::Diags) -> usize
    requires start < text.len(),
{
    let n: usize = text.len();
    let c1: u32 = at(text, start, 1);
    let mut base: u64 = 10;
    if at(text, start, 0) == 48 {
        if c1 == 120 {
            base = 16;
        } else if c1 == 111 {
            base = 8;
        } else if c1 == 98 {
            base = 2;
        }
    }
    let mut i: usize = start;
    if base != 10 {
        i = fwd(start, 2, n);
    }
    let mut v: wide::U128 = wide::zero();
    let mut overflow: bool = false;
    let mut any: bool = false;
    let mut bad: bool = false;
    let mut bad_at: usize = 0;
    while i < n && (digit(at(text, i, 0)) || at(text, i, 0) == 95 || base == 16 && hexval(at(text, i, 0)) < 16)
        invariant i <= n, base == 10 || base == 16 || base == 8 || base == 2,
        decreases n - i,
    {
        let c: u32 = at(text, i, 0);
        if c != 95 {
            any = true;
            let d: u64 = hexval(c) as u64;
            if d >= base {
                if !bad {
                    bad = true;
                    bad_at = i;
                }
            } else {
                match wide::mul_add(v, base, d) {
                    None => { overflow = true; },
                    Some(x) => { v = x; },
                }
            }
        }
        i = i + 1;
    }
    let digits_end: usize = i;
    let mut name: String = String::from("decimal");
    let mut radix: ast::Radix = ast::Radix::Dec;
    if base == 16 {
        name = String::from("hexadecimal");
        radix = ast::Radix::Hex;
    } else if base == 8 {
        name = String::from("octal");
        radix = ast::Radix::Oct;
    } else if base == 2 {
        name = String::from("binary");
        radix = ast::Radix::Bin;
    }
    if bad {
        let mut m: String = joined("`", cut(text, bad_at, bad_at.saturating_add(1)).as_str(), "` is not ");
        if base == 8 {
            m.push_str("an ");
        } else {
            m.push_str("a ");
        }
        m.push_str(name.as_str());
        m.push_str(" digit");
        let mut h: String = String::from(name.as_str());
        if base == 2 {
            h.push_str(" digits are `0` and `1`");
        } else {
            h.push_str(" digits are `0` to `7`");
        }
        h.push_str("; write the value in another base (`0x` hexadecimal, or decimal)");
        diags.push(diag::fix(diag::new("E0108", span(file, bad_at, bad_at.saturating_add(1)), m.as_str()), h.as_str(), None));
    }
    let no_digits: bool = !any && base != 10;
    if no_digits {
        let mut m: String = joined("`", cut(text, start, digits_end).as_str(), "` has no ");
        m.push_str(name.as_str());
        m.push_str(" digits");
        let h: String = joined("write the digits after the prefix: `", ast::radix_text(radix, wide::zero()).as_str(), "`");
        diags.push(diag::fix(diag::new("E0108", span(file, start, digits_end), m.as_str()), h.as_str(), None));
    }
    if word(at(text, i, 0)) {
        let slo: usize = i;
        while i < n && word(at(text, i, 0))
            decreases n - i,
        {
            i = i + 1;
        }
        let suffix: String = cut(text, slo, i);
        if !no_digits {
            let g: diag::Diag = diag::new("E0104", span(file, start, i), joined("literal suffix `", suffix.as_str(), "` is not allowed").as_str());
            if int_type(suffix.as_str()) {
                diags.push(diag::fix(g, "remove the suffix", Some(cut(text, start, digits_end))));
            } else {
                diags.push(diag::fix(g, "integer literals are digits in base 10, or after `0x`, `0o` or `0b`", None));
            }
        }
    }
    if overflow {
        diags.push(diag::new("E0105", span(file, start, i), "integer literal does not fit in 128 bits"));
    }
    out.push(Token { tok: Tok::Int(v, radix), span: span(file, start, i) });
    i
}

#[effects(alloc)]
fn render(d: &Diag, sm: &source::SourceMap) -> String {
    let a: source::Pos = sm.line_col(d.span.file, d.span.lo);
    let b: source::Pos = sm.line_col(d.span.file, d.span.hi);
    let mut s: String = String::from("{\"code\":");
    std::json::push_string(&mut s, d.code.as_str());
    s.push_str(",\"sev\":\"");
    push_severity(&mut s, d.code.as_str());
    s.push_str("\",\"message\":");
    std::json::push_string(&mut s, d.message.as_str());
    s.push_str(",\"file\":");
    sm.push_name(&mut s, d.span.file);
    s.push_str(",\"line\":");
    std::num::push_u64(&mut s, a.line as u64);
    s.push_str(",\"col\":");
    std::num::push_u64(&mut s, a.col as u64);
    s.push_str(",\"end_line\":");
    std::num::push_u64(&mut s, b.line as u64);
    s.push_str(",\"end_col\":");
    std::num::push_u64(&mut s, b.col as u64);
    match &d.obligation {
        None => {},
        Some(o) => { s.push_str(",\"obligation\":"); std::json::push_string(&mut s, o.as_str()); },
    }
    match &d.bounded {
        None => {},
        Some(k) => { s.push_str(",\"bounded\":{\"b\":"); std::num::push_i64(&mut s, k.b); s.push_str(",\"l\":"); std::num::push_u64(&mut s, k.l as u64); s.push_str("}"); },
    }
    match &d.fix {
        None => {},
        Some(f) => { s.push_str(",\"fix\":{\"message\":"); std::json::push_string(&mut s, f.message.as_str()); match &f.replacement { None => {}, Some(r) => { s.push_str(",\"replacement\":"); std::json::push_string(&mut s, r.as_str()); }, } s.push_str("}"); },
    }
    s.push_str("}");
    s
}

